    "test": {
      "summary": "run the bounded L1-L4 test ladder without accidental whole-suite work",
      "owner": "runtime",
      "verbs": {
        "affected": {
          "summary": "the specs related to the changed functions (--by file: every importer); --run runs each once",
          "owner": "runtime",
          "positional": [],
          "flags": [
            {
              "name": "base",
              "type": "string",
              "summary": "ref to diff against (default: the merge-base with main, else origin/main)"
            },
            {
              "name": "changed",
              "type": "list",
              "summary": "explicit changed repository paths instead of the diff"
            },
            {
              "name": "by",
              "type": "string",
              "summary": "symbol (default: the specs related to the changed functions) or file (every spec importing a changed file)"
            },
            {
              "name": "run",
              "type": "boolean",
              "summary": "run the selected spec files, one per process, inside the time budget"
            },
            {
              "name": "plan",
              "type": "boolean",
              "summary": "print the selected files with the reason each is in the set; run nothing"
            },
            {
              "name": "concurrency",
              "type": "number",
              "summary": "override automatic file concurrency with a positive integer"
            },
            {
              "name": "root",
              "type": "string",
              "summary": "repository root (default: the command cwd)"
            }
          ],
          "exit": {
            "0": "selection printed, or every selected file passed",
            "1": "a selected spec file was red",
            "2": "no base to diff against, or the time budget ended before every selected file started"
          },
          "json": "starci/test-affected@1",
          "examples": [
            "starci test affected",
            "starci test affected --run",
            "starci test affected --changed scripts/machine/ladder-test.mjs --run"
          ],
          "editions": [
            "full"
          ],
          "impl": {
            "module": "scripts/supervisor/affected-test.mjs",
            "export": "testAffected"
          },
          "effect": "host",
          "roles": [
            "worker",
            "lead",
            "coordinator",
            "release",
            "owner"
          ],
          "conventions": [
            "Everyday verification after npm run check; the whole suite is the merged-tree run and the release cut.",
            "The set is computed - each changed .mjs symbol is followed by name through its importers, callers and CLI verbs.",
            "What cannot be followed by name (yaml, templates, load-time statements, no base, the depth bound) keeps the file-level rule, named in the report.",
            "The report names every symbol with its specs and why, and every file that fell back; --json carries them; never larger than --by file.",
            "A large set is never refused; it runs in parallel shards inside the printed time budget, and files not started when it ends are listed.",
            "The --plan flag prints each selected file with the reason it is in the set; a --run answer carries a receipt (base, tip, passed, total) a gate can require.",
            "A generated output maps to its generator's specs; an append-only change to a data file to the specs that name it or its readers.",
            "A red file is fixed and run again, then the affected set once; never the whole suite.",
            "Each file is its own low-priority node process with the four preloads, at the concurrency of test-concurrency.yaml."
          ]
        },
        "run": {
          "summary": "run the specs selected for one local ladder level",
          "owner": "runtime",
          "positional": [],
          "flags": [
            {
              "name": "level",
              "type": "enum",
              "enum": [
                "L1",
                "L2",
                "L3",
                "L4"
              ],
              "required": true,
              "summary": "bounded local test level"
            },
            {
              "name": "changed",
              "type": "list",
              "summary": "changed repository paths used for L1 selection"
            },
            {
              "name": "against",
              "type": "string",
              "default": "main",
              "summary": "local main ref used for L2 and L3 selection"
            },
            {
              "name": "spec",
              "type": "list",
              "summary": "explicit spec files at L1 only"
            },
            {
              "name": "concurrency",
              "type": "number",
              "summary": "override automatic CPU/RAM file concurrency with a positive integer"
            },
            {
              "name": "root",
              "type": "string",
              "summary": "repository root (default is the command cwd)"
            },
            {
              "name": "release-cut",
              "type": "boolean",
              "summary": "confirm an owner or release-role L4 release-cut run"
            }
          ],
          "exit": {
            "0": "selected specs passed",
            "1": "a check or spec was red",
            "2": "usage or ladder policy refusal"
          },
          "json": "starci/test-run@1",
          "examples": [
            "starci test run --level L1 --changed scripts/machine/ladder-test.mjs",
            "starci test run --level L2 --against main --json",
            "starci test run --level L3 --against main"
          ],
          "editions": [
            "full"
          ],
          "impl": {
            "module": "scripts/machine/ladder-test.mjs",
            "export": "testRun"
          },
          "effect": "host",
          "roles": [
            "worker",
            "lead",
            "coordinator",
            "release",
            "owner"
          ],
          "conventions": [
            "Use L1 while working, L2 before asking for a land, and L3 when an IO slot changed.",
            "Never run the whole suite outside L4; L4 belongs to starci release cut and L5 belongs to CI.",
            "L2 and L3 need a clean committed tree, run the full check first, and hold the one host test lock.",
            "A red L2 or L3 selection is re-run once serially; a green re-run is recorded as a flake, never skipped.",
            "File concurrency uses fresh idle CPU and free RAM under modules/supervisor/test-concurrency.yaml; --concurrency overrides it.",
            "The result and spec log retain the concurrency decision and host measurements."
          ]
        }
      }
    },
